# p2 is a recursive function that performs binary search on a given portion of the array.
def p2(arr, start, end, target) -> int:
    if start >= end:
        return -1
    else:
        mid = (start + end) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return p2(arr, mid + 1, end, target)
        elif arr[mid] > target:
            return p2(arr, start, mid, target)

# p1 is the main function that initiates the search.
def p1(array, target):
