В nginx для перенаправления IP нужно использовать директивы "proxy_set_header". В этом случае нужно указать сервер как прокси и изменить заголовки так, чтобы на удалённой стороне в $_SERVER['REMOTE_ADDR'] отображался нужный вам IP-адрес. Это можно сделать при настройке конфигурации посредством редактирования конфигурационного файла и добавлением правильных директив.

Пример настройки nginx может выглядеть так:

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://another_server_ip:port;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP 1.1.1.1; # Устанавливает в $_SERVER['REMOTE_ADDR'] нужный IP-адрес
        proxy_set_header X-Forwarded-For 1.1.1.1; # Используется в $_SERVER['HTTP_X_FORWARDED_FOR']
    }
}

